#!/usr/bin/env python3
"""End-to-end raw SHA stdout protocol checks for the four LSQ/data-control callers.

Uses only Python's standard library. It creates isolated UTF-8/space fixture trees
and fake sha256sum/git executables under build/functional; no source RTL is edited,
no real Git command is invoked, and no /tmp paths are used.
"""
from __future__ import annotations

import base64
import hashlib
import json
import locale
import os
import re
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import zlib

ROOT = Path(__file__).resolve().parents[2]
AUTH = ROOT / "build" / "functional"
SOURCES = (
    "sim/functional/test_lsq.sh",
    "sim/functional/test_lsq_driver.sh",
    "sim/functional/test_data_control.sh",
    "sim/functional/test_data_control_driver.sh",
    "sim/functional/tb_lsq_semantics.sv",
    "sim/functional/tb_data_control.sv",
    "scripts/env.sh",
    "rtl/back2/lsq_simple.v",
    "rtl/back2/back2_params.vh",
)
BASE201_ZLIB_B64 = ""
BASE0DA_ZLIB_B64 = ""
HEADER_SHA = "066c8a7a30eac41c81f64788a3c3f80c4330f2ebec908ba5f940ad9bd1b48e34"
BASE_SHA = {
    "201acf61": "05d739e3649f33967dca46879ce57ae2cc825a31467b48d18d972a9ab41fd41c",
    "0da0e14": "2e084792d05db0d47ed4cc6e329edab9d3dc3b53536cb5c632e10be85b611e6c",
}
MODES = ("extra_lf", "many_lf", "no_lf", "nul", "cr", "wrong_path", "junk", "rc9")

FAKE_SHA = r'''#!/usr/bin/env python3
import json, os, pathlib, subprocess, sys
root = pathlib.Path(os.environ["SHA_CAPTURE_DIR"])
root.mkdir(parents=True, exist_ok=True)
nums = root / "counter"
try: n = int(nums.read_text())
except FileNotFoundError: n = 0
n += 1
nums.write_text(str(n))
slot = root / ("call-%04d" % n)
slot.mkdir()
argv = [os.fsdecode(x) for x in sys.argv[1:]]
real = subprocess.run([os.environ["SHA_REAL"], *argv], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
mode = os.environ.get("SHA_INJECT_MODE", "valid")
want = int(os.environ.get("SHA_TARGET_ARGC", "-1"))
seen = root / "target-seen"
target = len(argv) == want and (mode == "valid" or not seen.exists())
injected = target and mode != "valid"
if injected: seen.write_text(str(n))
original = real.stdout
toolout = original
if injected:
    if mode == "extra_lf": toolout = original + b"\n"
    elif mode == "many_lf": toolout = original + b"\n\n"
    elif mode == "no_lf": toolout = original.rstrip(b"\n")
    elif mode == "nul": toolout = original[:7] + b"\0" + original[7:]
    elif mode == "cr": toolout = original.replace(b"\n", b"\r\n")
    elif mode == "wrong_path":
        cut = original.find(b"\n")
        row = original[:cut]
        toolout = row[:-1] + (b"X" if row[-1:] != b"X" else b"Y") + original[cut:]
    elif mode == "junk":
        cut = original.find(b"\n")
        toolout = b"not-a-digest  garbage\n" + original[cut+1:]
    elif mode == "order":
        rows = original.splitlines(keepends=True)
        if len(rows) == 3: rows[0], rows[1] = rows[1], rows[0]
        else: toolout = b"wrong-row-count\n"
        if len(rows) == 3: toolout = b"".join(rows)
    elif mode == "rc9": pass
    else: raise SystemExit("unknown injection mode: " + mode)
real.stdout and (slot / "real.stdout").write_bytes(original)
(slot / "real.stderr").write_bytes(real.stderr)
(slot / "tool.stdout").write_bytes(toolout)
toolrc = 9 if injected and mode == "rc9" else real.returncode
meta = {"argv": argv, "arg_count": len(argv), "real_rc": real.returncode,
        "tool_rc": toolrc, "injected": injected, "target_hit": target,
        "mode": mode if injected else "valid",
        "real_stdout_sha256": __import__("hashlib").sha256(original).hexdigest(),
        "tool_stdout_sha256": __import__("hashlib").sha256(toolout).hexdigest()}
(slot / "meta.json").write_text(json.dumps(meta, ensure_ascii=False, sort_keys=True) + "\n")
sys.stdout.buffer.write(toolout)
sys.stderr.buffer.write(real.stderr)
raise SystemExit(toolrc)
'''

FAKE_GIT = r'''#!/usr/bin/env python3
import json, os, pathlib, sys
args = sys.argv[1:]
log = pathlib.Path(os.environ["GIT_CAPTURE_LOG"])
with log.open("a", encoding="utf-8") as f: f.write(json.dumps(args, ensure_ascii=False) + "\n")
if len(args) >= 2 and args[0] == "-C": args = args[2:]
if args and args[0] == "rev-parse": raise SystemExit(1)
if len(args) == 3 and args[0] == "cat-file" and args[1] == "-e":
    commit = args[2].removesuffix("^{commit}")
    raise SystemExit(0 if commit in ("201acf61", "0da0e14") else 1)
if len(args) == 2 and args[0] == "show" and ":" in args[1]:
    commit, rel = args[1].split(":", 1)
    key = "201acf61" if commit.startswith("201acf61") else "0da0e14" if commit.startswith("0da0e14") else ""
    if key and rel in ("rtl/back2/lsq_simple.v", "rtl/back2/back2_params.vh"):
        p = pathlib.Path(os.environ["SHA_BASELINE_ROOT"]) / key / rel
        sys.stdout.buffer.write(p.read_bytes())
        raise SystemExit(0)
raise SystemExit(2)
'''


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def json_write(path: Path, value) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + "\n", encoding="utf-8")


def source_manifest() -> dict[str, str]:
    return {rel: sha256(ROOT / rel) for rel in SOURCES}


def make_baselines(repo: Path) -> Path:
    out = repo / ".sha-protocol-baselines"
    blobs = {
        "201acf61": BASE201_ZLIB_B64,
        "0da0e14": BASE0DA_ZLIB_B64,
    }
    for commit, encoded in blobs.items():
        if "__BASE" in encoded:
            raise RuntimeError("embedded old baseline data missing")
        payload = zlib.decompress(base64.b64decode(encoded))
        if hashlib.sha256(payload).hexdigest() != BASE_SHA[commit]:
            raise RuntimeError(f"embedded baseline hash mismatch: {commit}")
        dest = out / commit / "rtl/back2/lsq_simple.v"
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(payload)
        header = repo / "rtl/back2/back2_params.vh"
        if sha256(header) != HEADER_SHA:
            raise RuntimeError("fixture header hash mismatch")
        shutil.copy2(header, out / commit / "rtl/back2/back2_params.vh")
    return out


def make_fixture(work: Path, family: str) -> tuple[Path, Path, dict[str, str], dict[str, str]]:
    before = source_manifest()
    repo = work / (family + " repo Ω with spaces")
    copied: dict[str, str] = {}
    for rel in SOURCES:
        src, dst = ROOT / rel, repo / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)
        copied[rel] = sha256(dst)
    if copied != before:
        raise RuntimeError(f"source-copy identity mismatch: {family}")
    dut = repo / "DUT 输入 Ω with spaces"
    for rel in ("rtl/back2/lsq_simple.v", "rtl/back2/back2_params.vh"):
        dst = dut / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(repo / rel, dst)
        if sha256(dst) != copied[rel]:
            raise RuntimeError(f"DUT_ROOT copy identity mismatch: {rel}")
    make_baselines(repo)
    return repo, dut, before, copied


def make_tools(case_dir: Path) -> Path:
    bindir = case_dir / "fakebin"
    bindir.mkdir(parents=True)
    for name, body in (("sha256sum", FAKE_SHA), ("git", FAKE_GIT)):
        p = bindir / name
        p.write_text(body, encoding="utf-8")
        p.chmod(0o755)
    return bindir


def target_expected(family: str, caller: str, repo: Path, dut: Path, argc: int, argv: list[str]) -> bool:
    paths = argv[1:] if argv and argv[0] == "--" else argv
    if len(argv) != argc:
        return False
    if caller == "package":
        tb = "tb_lsq_semantics.sv" if family == "lsq" else "tb_data_control.sv"
        return paths == [str(dut / "rtl/back2/lsq_simple.v"), str(dut / "rtl/back2/back2_params.vh"), str(repo / "sim/functional" / tb)]
    if argc == 2:
        if family == "lsq": return paths == [str(repo / "rtl/back2/lsq_simple.v")]
        return paths[0].endswith("/deps_cur/rtl/back2/lsq_simple.v")
    pkg = "test_lsq.sh" if family == "lsq" else "test_data_control.sh"
    tb = "tb_lsq_semantics.sv" if family == "lsq" else "tb_data_control.sv"
    return (len(paths) == 3 and paths[0].endswith("/sim/functional/" + pkg)
            and paths[1].endswith("/sim/functional/" + tb) and paths[2].endswith("/scripts/env.sh"))


def valid_sha_stdout(raw: bytes, argv: list[str]) -> bool:
    paths = argv[1:] if argv and argv[0] == "--" else argv
    if b"\0" in raw or b"\r" in raw or not raw.endswith(b"\n"):
        return False
    rows = raw.split(b"\n")[:-1]
    if len(rows) != len(paths):
        return False
    for row, path in zip(rows, paths):
        match = re.fullmatch(rb"([0-9a-f]{64})  (.*)", row)
        if not match or match.group(2) != os.fsencode(path):
            return False
    return True


def tool_records(case_dir: Path) -> list[dict]:
    out = []
    for p in sorted((case_dir / "sha-calls").glob("call-*/meta.json")):
        out.append(json.loads(p.read_text(encoding="utf-8")))
    return out


def find_driver_log(repo: Path, outroot: Path, case_id: str) -> Path | None:
    logs = list(outroot.glob("run-*/driver.log"))
    return logs[0] if len(logs) == 1 else None


def package_reason(family: str, mode: str) -> str:
    p = "FUNCTIONAL_LSQ" if family == "lsq" else "FUNCTIONAL_DATA_CONTROL"
    reason = {
        "extra_lf": "sha256_lines=4", "many_lf": "sha256_lines=5",
        "no_lf": "sha256_unterminated", "nul": "sha256_bytes", "cr": "sha256_bytes",
        "wrong_path": "sha256_path line=1", "order": "sha256_path line=1",
        "junk": "sha256_format line=1", "rc9": "sha256sum_rc=9",
    }[mode]
    return f"{p}: FAIL reason={reason}"


def caller_reason(family: str, caller: str, argc: int, mode: str) -> str:
    if family == "lsq":
        if mode == "rc9": return "rc=9" if argc == 2 else "shared_sha_rc=9"
        reason = {"extra_lf": "lines=2" if argc == 2 else "lines=4",
                  "many_lf": "lines=3" if argc == 2 else "lines=5",
                  "no_lf": "sha256_unterminated", "nul": "sha256_bytes", "cr": "sha256_bytes",
                  "wrong_path": "sha256_path line=1", "order": "sha256_path line=1",
                  "junk": "sha256_format line=1"}[mode]
        if argc == 2:
            return reason
        if reason.startswith("lines="):
            reason = "sha256_" + reason
        return "shared_sha_invalid reason=" + reason
    if mode == "rc9": return "rc=9" if argc == 2 else "shared_sha_rc=9"
    reason = {"extra_lf": "sha_lines=2" if argc == 2 else "sha_lines=4",
              "many_lf": "sha_lines=3" if argc == 2 else "sha_lines=5",
              "no_lf": "sha_unterminated", "nul": "sha_bytes", "cr": "sha_bytes",
              "wrong_path": "sha_path line=1", "order": "sha_path line=1",
              "junk": "sha_format line=1"}[mode]
    return reason if argc == 2 else "shared_sha_invalid reason=" + reason


def captured_raw_matches(repo: Path, outroot: Path, family: str, caller: str, argc: int, payload: bytes) -> bool:
    if caller == "package":
        pattern = "sha_pre.txt" if family == "lsq" else "sha_pre.raw"
    else:
        pattern = "sha-one-*" if argc == 2 else "sha-shared-*"
    candidates = list(outroot.rglob(pattern))
    return any(p.is_file() and p.read_bytes() == payload for p in candidates)


def execute_case(work: Path, family: str, caller: str, mode: str, argc: int | None = None) -> dict:
    case_id = f"{family}-{caller}-{'a'+str(argc)+'-' if argc else ''}{mode}"
    case_dir = work / "cases" / case_id
    case_dir.mkdir(parents=True)
    repo = work / "fixtures" / (family + " repo Ω with spaces")
    dut = repo / "DUT 输入 Ω with spaces"
    tool_dir = make_tools(case_dir)
    auth = repo / "build/functional"
    outroot = auth / ("protocol-" + case_id)
    outroot.mkdir(parents=True)
    if caller == "package":
        script = repo / "sim/functional" / ("test_lsq.sh" if family == "lsq" else "test_data_control.sh")
        cmd = ["bash", str(script)]
        target_argc = 4
    elif family == "lsq":
        script = repo / "sim/functional/test_lsq_driver.sh"
        cmd = ["bash", str(script), "--self-test"]
        target_argc = argc
    else:
        script = repo / "sim/functional/test_data_control_driver.sh"
        cmd = ["bash", str(script)]
        target_argc = argc
    env = os.environ.copy()
    env.update({
        "PATH": str(tool_dir) + os.pathsep + env.get("PATH", ""),
        "SHA_REAL": shutil.which("sha256sum") or "/usr/bin/sha256sum",
        "SHA_CAPTURE_DIR": str(case_dir / "sha-calls"),
        "SHA_INJECT_MODE": mode,
        "SHA_TARGET_ARGC": str(target_argc),
        "GIT_CAPTURE_LOG": str(case_dir / "git-calls.jsonl"),
        "SHA_BASELINE_ROOT": str(repo / ".sha-protocol-baselines"),
        "RV32_FUNCTIONAL_PKG_OUT_DIR": str(outroot),
        "LC_ALL": "C.UTF-8",
    })
    for key in ("LSQ_EXPECT", "DC_EXPECT", "DUT_ROOT", "OUT_DIR"):
        env.pop(key, None)
    if caller == "package": env["DUT_ROOT"] = str(dut)
    stdout_path, stderr_path = case_dir / "stdout.bin", case_dir / "stderr.bin"
    try:
        proc = subprocess.run(cmd, cwd=repo, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=600)
        rc = proc.returncode
        stdout, stderr = proc.stdout, proc.stderr
    except subprocess.TimeoutExpired as e:
        rc = 124
        stdout, stderr = e.stdout or b"", e.stderr or b""
    stdout_path.write_bytes(stdout)
    stderr_path.write_bytes(stderr)
    dlog = find_driver_log(repo, outroot, case_id) if caller == "driver" else None
    driver_text = dlog.read_text(encoding="utf-8", errors="replace") if dlog else ""
    combined = stdout.decode("utf-8", "replace") + "\n" + stderr.decode("utf-8", "replace") + "\n" + driver_text
    records = tool_records(case_dir)
    target_records = [r for r in records if r["target_hit"] and target_expected(family, caller, repo, dut, target_argc, r["argv"])]
    negative = mode != "valid"
    failures = []
    expected_rc = 1 if negative else 0
    if rc != expected_rc: failures.append(f"caller_rc={rc}, expected={expected_rc}")
    if "PASS" in combined and negative: failures.append("PASS leaked on negative case")
    if not target_records: failures.append("target sha256sum argv not consumed by intended caller")
    if negative:
        diagnostic = package_reason(family, mode) if caller == "package" else caller_reason(family, caller, target_argc, mode)
        if diagnostic not in combined: failures.append(f"diagnostic missing: {diagnostic}")
        if len(target_records) != 1: failures.append(f"target record count={len(target_records)}")
        if target_records:
            rec = target_records[0]
            slot = case_dir / "sha-calls" / f"call-{next(i for i, r in enumerate(records,1) if r is rec):04d}"
            if rec["real_rc"] != 0: failures.append(f"real sha rc={rec['real_rc']} before mutation")
            if rec["tool_rc"] != (9 if mode == "rc9" else 0): failures.append(f"tool rc={rec['tool_rc']}")
            if not (slot / "real.stdout").exists() or not (slot / "tool.stdout").exists(): failures.append("raw stdout archive missing")
            real_raw = (slot / "real.stdout").read_bytes()
            if not valid_sha_stdout(real_raw, rec["argv"]): failures.append("real sha256sum stdout was not exact valid input")
            if (slot / "real.stderr").read_bytes(): failures.append("real sha256sum emitted stderr for valid inputs")
            if not captured_raw_matches(repo, outroot, family, caller, target_argc, (slot / "tool.stdout").read_bytes()):
                failures.append("actual caller raw capture does not equal injected stdout")
    else:
        if family == "lsq" and caller == "package":
            if "FUNCTIONAL_LSQ: PASS" not in combined or "LSQ_VECTORS total=18 nonzero=18 checks=285 fails=0 defect=0 xz=0" not in combined:
                failures.append("LSQ fixed positive contract missing")
        elif family == "data_control" and caller == "package":
            if "FUNCTIONAL_DATA_CONTROL: PASS" not in combined or "DC_VECTORS total=16 nonzero=16 checks=113 fails=0 defect=0 xz=0" not in combined:
                failures.append("data-control fixed positive contract missing")
        elif family == "lsq" and caller == "driver":
            if "LSQ_DRIVER: PASS" not in combined or "LSQ_DRIVER: selftest=ok" not in combined:
                failures.append("LSQ driver self-test positive missing")
        elif family == "data_control" and caller == "driver":
            if "DC_DRIVER: PASS phases=5 selftests=8" not in combined:
                failures.append("data-control driver positive contract missing")
        if any(not r["target_hit"] for r in target_records): failures.append("target hit not recorded")
        for rec in target_records:
            if rec["real_rc"] != 0 or rec["tool_rc"] != 0: failures.append("valid SHA invocation nonzero")
            slot = case_dir / "sha-calls" / f"call-{records.index(rec)+1:04d}"
            raw = (slot / "real.stdout").read_bytes()
            paths = rec["argv"][1:] if rec["argv"] and rec["argv"][0] == "--" else rec["argv"]
            if not valid_sha_stdout(raw, rec["argv"]):
                failures.append("valid raw stdout not exact LF rows/hex/ordered paths")
            if not captured_raw_matches(repo, outroot, family, caller, target_argc, raw):
                failures.append("valid raw stdout not captured by caller")
    if not any((b" " in os.fsencode(p) and any(c >= 128 for c in os.fsencode(p))) for r in target_records for p in (r["argv"][1:] if r["argv"] and r["argv"][0] == "--" else r["argv"])):
        failures.append("UTF-8 plus space path not present in target argv")
    git_log = case_dir / "git-calls.jsonl"
    if family == "data_control" and caller == "driver":
        if not git_log.exists(): failures.append("fake Git not used")
        if any("rev-parse" not in line and not any(k in line for k in ("cat-file", "show")) for line in git_log.read_text(encoding="utf-8").splitlines()):
            failures.append("unexpected fake Git invocation")
    target_real_rcs = sorted({r["real_rc"] for r in target_records})
    target_tool_rcs = sorted({r["tool_rc"] for r in target_records})
    result = {"case": case_id, "family": family, "caller": caller, "mode": mode,
              "target_argc": target_argc, "caller_rc": rc, "target_sha_calls": len(target_records),
              "target_real_rcs": target_real_rcs, "target_tool_rcs": target_tool_rcs,
              "logged_sha_invocations": len(records), "diagnostic": "positive" if not negative else diagnostic,
              "result": "FAIL" if failures else "PASS", "failures": failures,
              "stdout": str(stdout_path), "stderr": str(stderr_path),
              "driver_log": str(dlog) if dlog else None,
              "sha_calls_dir": str(case_dir / "sha-calls")}
    json_write(case_dir / "result.json", result)
    return result


def verify_identity(work: Path, family: str, before: dict[str, str], copied_pre: dict[str, str]) -> dict:
    repo = work / "fixtures" / (family + " repo Ω with spaces")
    source_after = source_manifest()
    copied_after = {rel: sha256(repo / rel) for rel in SOURCES}
    dut_after = {rel: sha256(repo / "DUT 输入 Ω with spaces" / rel)
                 for rel in ("rtl/back2/lsq_simple.v", "rtl/back2/back2_params.vh")}
    baseline_after = {commit: sha256(repo / ".sha-protocol-baselines" / commit / "rtl/back2/lsq_simple.v")
                      for commit in BASE_SHA}
    dut_ok = all(dut_after[rel] == source_after[rel] for rel in dut_after)
    baseline_ok = baseline_after == BASE_SHA
    status = (before == copied_pre == copied_after == source_after) and dut_ok and baseline_ok
    record = {"family": family, "source_pre": before, "copy_pre": copied_pre,
              "copy_post": copied_after, "source_post": source_after, "dut_copy_post": dut_after,
              "embedded_baseline_post": baseline_after,
              "sourcepre_copyeq_bothafter": status}
    json_write(work / "identity" / f"{family}.json", record)
    return record


def main() -> int:
    if len(sys.argv) != 1:
        raise RuntimeError("unknown arguments; runner takes no options")
    locale.setlocale(locale.LC_ALL, "C.UTF-8")
    AUTH.mkdir(parents=True, exist_ok=True)
    work = Path(tempfile.mkdtemp(prefix="sha-protocol-", dir=AUTH))
    work.mkdir(exist_ok=True)
    runner_hash_pre = sha256(Path(__file__).resolve())
    cases: list[dict] = []
    before_by_family: dict[str, tuple[dict[str, str], dict[str, str]]] = {}
    for family in ("lsq", "data_control"):
        repo, dut, before, copied_pre = make_fixture(work / "fixtures", family)
        before_by_family[family] = (before, copied_pre)
        # The fixture pathname itself is the UTF-8+space control; assert before any call.
        encoded = os.fsencode(repo)
        if b" " not in encoded or not any(c >= 128 for c in encoded):
            raise RuntimeError("fixture path lacks both space and UTF-8 bytes")
        # Package: valid single-LF control, eight malformed/rc controls, plus 3-input order.
        cases.append(execute_case(work, family, "package", "valid"))
        for mode in MODES: cases.append(execute_case(work, family, "package", mode))
        cases.append(execute_case(work, family, "package", "order"))
        # Driver single-file caller: valid and all non-order fault modes.
        cases.append(execute_case(work, family, "driver", "valid", 2))
        for mode in MODES: cases.append(execute_case(work, family, "driver", mode, 2))
        # Driver shared three-input caller: valid, faults, and row-order mutation.
        cases.append(execute_case(work, family, "driver", "valid", 4))
        for mode in MODES: cases.append(execute_case(work, family, "driver", mode, 4))
        cases.append(execute_case(work, family, "driver", "order", 4))
    identities = [verify_identity(work, family, *before_by_family[family]) for family in before_by_family]
    runner_hash_post = sha256(Path(__file__).resolve())
    if runner_hash_pre != runner_hash_post:
        raise RuntimeError("runner source changed during execution")
    bad = [c for c in cases if c["result"] != "PASS"]
    if any(not row["sourcepre_copyeq_bothafter"] for row in identities):
        bad.append({"case": "source_identity", "result": "FAIL"})
    summary = {"cases": len(cases), "pass": len(cases) - len(bad), "fail": len(bad),
               "positive_controls": sum(1 for c in cases if c["mode"] == "valid"),
               "negative_controls": sum(1 for c in cases if c["mode"] != "valid"),
               "source_identity_ok": not any(not r["sourcepre_copyeq_bothafter"] for r in identities),
               "runner_sha256": runner_hash_pre, "artifact_root": str(work)}
    json_write(work / "summary.json", summary)
    for row in cases:
        print("CASE " + json.dumps({k: row[k] for k in ("case", "result", "caller_rc", "target_sha_calls", "target_real_rcs", "target_tool_rcs", "diagnostic", "sha_calls_dir")}, ensure_ascii=False, sort_keys=True))
    print("SHA_PROTOCOL " + json.dumps(summary, ensure_ascii=False, sort_keys=True))
    return 1 if bad else 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(f"SHA_PROTOCOL: FAIL reason={type(exc).__name__}:{exc}", file=sys.stderr)
        raise SystemExit(1)
